-- Algebra 2 final module. Run seed_algebra2_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'algebra-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Ministry Growth and Budget Model Project$j$, $j${"prompt": "Plan the growth and the budget of a small ministry or school program. Show all work, label each part, and write complete sentences. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men; A good steward plans carefully and serves with all his heart. Use the algebra you learned in this course to plan yours.\n\nPart 1: Functions and Transformations. A program serves f(x) = 40 + 5x families after x months. Its cost in dollars is g(x) = 12x + 100 per month for supplies. Find the composition g(f(x)) and explain what it measures. Find the inverse of f and tell what the inverse tells the director. Describe how the graph of h(x) = f(x minus 3) + 10 compares with the graph of f.\n\nPart 2: Quadratic Planning. The weekly income from an event is I(p) = negative 5p squared + 100p, where p is the ticket price in dollars. Find the vertex and explain what it means. Find the prices at which the income is 320 dollars, using the quadratic formula or factoring. Solve the inequality negative 5p squared + 100p is at least 320 and explain what the solution says about pricing.\n\nPart 3: Polynomials. A storage box is made from a 12 inch by 18 inch sheet by cutting a square of side x from each corner. Write the volume V(x) as a polynomial in standard form and state the domain. Use technology to estimate the value of x that gives the largest volume. Divide x cubed minus 7x plus 6 by x minus 1 and use the quotient to find all of its zeros.\n\nPart 4: Radical, Rational and Absolute Value Models. The speed of a car in miles per hour that left a skid mark of d feet is modeled by s = the square root of (24d). Find the speed when d = 150 and the skid length when s = 30. A volunteer finishes a mailing in 6 hours and a helper in 3 hours. Write and solve a rational equation for the time working together. Solve |2x minus 5| less than 9 and explain what it could mean for a temperature that must stay within 9 degrees of 5 degrees.\n\nPart 5: Exponential Growth and Stewardship. A ministry fund starts with $4000 and earns 6 percent interest compounded monthly. Write the model, find the balance after 8 years, and use logarithms to find how long it takes to reach $8000. Compare it with simple interest at the same rate and with continuous compounding for 8 years. Then give two sentences of advice about saving, giving and avoiding unnecessary debt.\n\nPart 6: Systems and Data. A ministry sells two kinds of kits with a profit of 3 dollars on kit A and 2 dollars on kit B. Time limits the total to at most 6 kits and materials limit 2x + y to at most 8, with x kits of type A and y kits of type B. Graph the feasible region, list the vertices and find the best profit. Then decide whether the data (0, 3), (1, 6), (2, 11), (3, 18) fit a linear, quadratic or exponential model, write the model and predict the value at x = 5.\n\nPart 7: Reflection. In at least 100 words, explain how the mathematics of this course can help you serve with excellence, plan with wisdom and give an honest account of your results. Mention at least two function families you used and one limit of a model.", "rubric": "200 points. Part 1, functions and transformations: 24 points. Part 2, quadratic planning: 32 points. Part 3, polynomials: 30 points. Part 4, radical, rational and absolute value models: 32 points. Part 5, exponential growth and stewardship: 32 points. Part 6, systems and data: 32 points. Part 7, reflection: 12 points. Clear organization, correct units and complete sentences: 6 points. A score of 140 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Ministry Growth and Budget Model Project$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Algebra 2$j$, $j${"questions": [{"q": "If f(x) = 2x + 1 and g(x) = x squared, then f(g(3)) equals:", "options": ["28", "10", "19", "49"]}, {"q": "The inverse of f(x) = 3x minus 6 is:", "options": ["f inverse of x = (x + 6)/3", "f inverse of x = (x minus 6)/3", "f inverse of x = 3x + 6", "f inverse of x = 1/(3x minus 6)"]}, {"q": "(4 minus 3i)(2 + i) equals:", "options": ["8 minus 3i", "11 + 2i", "5 minus 2i", "11 minus 2i"]}, {"q": "The solutions of x squared + 2x + 5 = 0 are:", "options": ["negative 2 plus or minus i", "negative 1 plus or minus 2i", "1 plus or minus 2i", "negative 1 plus or minus 4i"]}, {"q": "The vertex of f(x) = x squared minus 6x + 5 is:", "options": ["(negative 3, negative 4)", "(3, 4)", "(6, 5)", "(3, negative 4)"]}, {"q": "When f(x) = x cubed minus 4x squared + 2x minus 7 is divided by x minus 3, the remainder is:", "options": ["3", "negative 7", "negative 10", "10"]}, {"q": "The end behavior of f(x) = negative 2x to the fourth + x squared minus 3 is:", "options": ["Both ends rise", "Falls left, rises right", "Both ends fall", "Rises left, falls right"]}, {"q": "32 to the power 3/5 equals:", "options": ["2", "8", "6", "96"]}, {"q": "Solving the square root of (2x + 9) = x + 3 and checking gives:", "options": ["x = 0 and x = negative 4", "No solution", "x = negative 4 only", "x = 0 only"]}, {"q": "The solution of |2x + 1| at most 7 is:", "options": ["x at most negative 4 or x at least 3", "x at most 3", "negative 3 at most x at most 4", "negative 4 at most x at most 3"]}, {"q": "The horizontal asymptote of f(x) = (3x minus 6)/(x + 1) is:", "options": ["y = negative 1", "y = 0", "y = negative 6", "y = 3"]}, {"q": "The solution of 5/(x minus 2) = 3/(x + 2) is:", "options": ["x = negative 2", "x = 8", "x = negative 8", "x = 2"]}, {"q": "The solution of 7 to the power x = 50, to the nearest thousandth, is:", "options": ["7.143", "2.010", "3.912", "1.945"]}, {"q": "$3000 invested at 4 percent compounded quarterly for 5 years grows to about:", "options": ["$3649.97", "$3600.00", "$3666.67", "$3660.57"]}, {"q": "For P = 2x + 3y over the region with vertices (0, 0), (7, 0), (4, 3) and (0, 5), the maximum value of P is:", "options": ["14", "17", "15", "0"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Algebra 2$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,1,3,2,2,1,3,3,3,2,1,3,1}'::int[], array[$j$g(3) = 9, and f(9) = 2(9) + 1 = 19.$j$,$j$Swap x and y and solve: x = 3y minus 6 gives y = (x + 6)/3.$j$,$j$8 + 4i minus 6i minus 3i squared = 8 minus 2i + 3 = 11 minus 2i.$j$,$j$The quadratic formula gives (negative 2 plus or minus the square root of negative 16)/2 = negative 1 plus or minus 2i.$j$,$j$The axis is x = 3 and f(3) = 9 minus 18 + 5 = negative 4.$j$,$j$By the Remainder Theorem, f(3) = 27 minus 36 + 6 minus 7 = negative 10.$j$,$j$Even degree with a negative leading coefficient falls on both ends.$j$,$j$The fifth root of 32 is 2, and 2 cubed is 8.$j$,$j$Squaring gives x squared + 4x = 0, but x = negative 4 fails the check.$j$,$j$Negative 7 at most 2x + 1 at most 7 gives negative 4 at most x at most 3.$j$,$j$The degrees are equal, so the asymptote is the ratio of leading coefficients, 3.$j$,$j$Cross multiplying gives 5x + 10 = 3x minus 6, so x = negative 8.$j$,$j$x = (log 50)/(log 7), about 2.010.$j$,$j$A = 3000(1.01) to the 20, about $3660.57.$j$,$j$P(4, 3) = 8 + 9 = 17, which exceeds 14 and 15.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Algebra 2$j$ on conflict (item_id) do nothing;
end
$seed$;
